{
  "name": "oc-mcp-plugin-manager",
  "version": "0.1.0",
  "description": "MCP manager for OpenCode 2: project toggles, refresh, reconnect, and sidebar hide rules.",
  "license": "MIT",
  "type": "module",
  "bin": {
    "oc-mcp-plugin-manager": "bin/cli.js"
  },
  "main": "./dist/server.js",
  "exports": {
    ".": {
      "import": "./dist/server.js"
    },
    "./server": {
      "import": "./dist/server.js",
      "config": "./dist/server.config.js"
    },
    "./tui": {
      "import": "./dist/tui.js",
      "config": "./dist/tui.config.js"
    }
  },
  "files": [
    "dist",
    "bin",
    "templates",
    "README.md",
    "LICENSE",
    "server.js",
    "tui.js"
  ],
  "engines": {
    "node": ">=20",
    "opencode": ">=2.0.16"
  },
  "scripts": {
    "build": "bun run build.ts",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "prepack": "bun run build.ts"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.0.16 <3",
    "@opencode/theme": ">=2.0.16 <3",
    "@opentui/core": ">=0.5.10",
    "@opentui/solid": ">=0.5.10",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opencode/theme": {
      "optional": true
    },
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode/client": "2.0.16",
    "@opencode/plugin": "2.0.16",
    "@opencode/schema": "2.0.16",
    "@opencode/theme": "2.0.16",
    "@opentui/core": "0.5.10",
    "@opentui/solid": "0.5.10",
    "@types/node": "24.12.2",
    "oc-mcp-manager-core": "workspace:*",
    "solid-js": "1.9.15",
    "typescript": "5.8.2",
    "zod": "4.1.8"
  },
  "publishConfig": {
    "access": "public"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "mcp",
    "mcp-manager"
  ],
  "dependencies": {
    "jsonc-parser": "^3.3.1"
  },
  "author": "d4n-sec",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/d4n-sec/oc-mcp-plugin-manager.git",
    "directory": "packages/v2"
  },
  "homepage": "https://github.com/d4n-sec/oc-mcp-plugin-manager#readme",
  "bugs": {
    "url": "https://github.com/d4n-sec/oc-mcp-plugin-manager/issues"
  }
}
